public class LogPurgeJob implements Schedulable {

    public void execute(SchedulableContext ctx) {
        Date thirtyDaysAgo = Date.today().addDays(-30);
        Date oneHundredEightyDaysAgo = Date.today().addDays(-180);

        List<FB_Integration_Log__c> toDelete = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (CreatedDate < :thirtyDaysAgo AND (Level__c != 'ERROR' OR Level__c = null))
            OR (CreatedDate < :oneHundredEightyDaysAgo AND Level__c = 'ERROR')
        ];

        if (!toDelete.isEmpty()) {
            delete toDelete;
        }
    }

    public static Id scheduleNightly() {
        String cronExpression = '0 2 * * * ?';
        return System.schedule('Log purge (nightly)', cronExpression, new LogPurgeJob());
    }
