public class OpportunityRollupService {

    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new Map<Id, Decimal>();
        }

        Integer year = DateTime.now().year();
        Date startOfYear = Date.newInstance(year, 1, 1);
        Date startOfNextYear = Date.newInstance(year + 1, 1, 1);

        // Pre-seed every requested account with 0 so that accounts with no
        // qualifying opportunities (or only null-amount opportunities) still
        // appear in the result.
        Map<Id, Decimal> result = new Map<Id, Decimal>();
        for (Id accId : accountIds) {
            result.put(accId, 0);
        }

        // Single aggregate query – respects the running user's sharing.
        List<AggregateResult> aggregates = [
            SELECT AccountId,
                   SUM(Amount) totalAmount
            FROM Opportunity
            WHERE IsWon = true
              AND CloseDate >= :startOfYear
              AND CloseDate < :startOfNextYear
              AND AccountId IN :accountIds
            GROUP BY AccountId
        ];

        // Overwrite the zero defaults with actual sums.
        for (AggregateResult ar : aggregates) {
            Id accId = (Id) ar.get('AccountId');
            Decimal sum = (Decimal) ar.get('totalAmount');
            if (accId != null) {
                result.put(accId, sum != null ? sum : 0);
            }
        }

        return result;
    }
}
