public without sharing class Accounts extends fflib_SObjects implements IAccounts {

    private List<Account> accounts;

    public Accounts(List<SObject> records) {
        super(records);
        this.accounts = (List<Account>) records;
    }

    public static IAccounts newInstance(List<Account> records) {
        return (IAccounts) Application.Domain.newInstance(Account.SObjectType, (List<SObject>) records);
    }

    public static IAccounts newInstance(Set<Id> accountIds) {
        return (IAccounts) Application.Domain.newInstance(Account.SObjectType, accountIds);
    }

    public Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public Type getType() {
        return Account.SObjectType;
    }

    public List<Account> getAccounts() {
        return accounts;
    }

    public IAccounts selectByRating(String rating) {
        List<Account> matching = new List<Account>();
        for (Account acc : accounts) {
            if (acc.Rating == rating) {
                matching.add(acc);
            }
        }
        return newInstance(matching);
    }

    public Set<Id> getOwnerIds() {
        Set<Id> ownerIds = new Set<Id>();
        for (Account acc : accounts) {
            if (acc.OwnerId != null) {
                ownerIds.add(acc.OwnerId);
            }
        }
        return ownerIds;
    }

    public void setRating(String rating) {
        for (Account acc : accounts) {
            acc.Rating = rating;
        }
    }

    public class Constructor extends Accounts {
        public Constructor(List<Account> records) {
            super((List<SObject>) records);
        }
    }
}
