    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        Map<String, Decimal> result = new Map<String, Decimal>();

        // Pre-seed every stage with 0 so a missing result never yields null
        for (String stage : STAGES) {
            result.put(stage, 0);
        }

        // Exactly four iterations → four SOQL queries, well within governor limits
        for (String stage : STAGES) {
            List<AggregateResult> aggregates = [
                SELECT SUM(Amount)
                FROM Opportunity
                WHERE StageName = :stage
                  AND CloseDate >= :fromDate
                  AND CloseDate <= :toDate
            ];

            Decimal total = 0;
            if (!aggregates.isEmpty() && aggregates[0].get('SUM(Amount)') != null) {
                total = (Decimal) aggregates[0].get('SUM(Amount)');
            }
            result.put(stage, total);
        }

        return result;
    }
}
