            Deal_Stage_Change__e evt = new Deal_Stage_Change__e();
            evt.Opportunity_Id__c = opp.Id;
            evt.Stage__c          = opp.StageName;
            evt.Amount__c         = opp.Amount;

            List<Database.SaveResult> batchResults = EventBus.publish(new List<Deal_Stage_Change__e>{ evt });
            results.add(batchResults[0]);
        }

        return results;
    }
}
