```javascript
import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

export default class QueueMonitor extends LightningElement {
    waiting;
    longestWaitMinutes;
    errorMessage;
    hasLoaded = false;
    isLoading = false;
    pollTimer;

    _visibilityHandler = () => this.onVisibilityChange();

    connectedCallback() {
        document.addEventListener('visibilitychange', this._visibilityHandler);
        if (document.visibilityState === 'visible') {
            this.loadStats();
            this.startPolling();
        }
    }

    disconnectedCallback() {
        this.stopPolling();
        document.removeEventListener('visibilitychange', this._visibilityHandler);
    }

    onVisibilityChange() {
        if (document.visibilityState === 'visible') {
            this.loadStats();
            if (!this.pollTimer) {
                this.startPolling();
            }
        }
    }

    startPolling() {
        if (this.pollTimer) return;
        this.pollTimer = setInterval(() => {
            if (document.visibilityState === 'hidden') return;
            if (this.isLoading) return;
            this.loadStats();
        }, 60000);
    }

    stopPolling() {
        if (this.pollTimer) {
            clearInterval(this.pollTimer);
            this.pollTimer = null;
        }
    }

    async loadStats() {
        if (this.isLoading) return;
        if (document.visibilityState === 'hidden') return;

        this.isLoading = true;
        try {
            const result = await getQueueStats();
            this.waiting = result.waiting;
            this.longestWaitMinutes = result.longestWaitMinutes;
            this.errorMessage = null;
            this.hasLoaded = true;
        } catch (error) {
            this.errorMessage = error.body.message;
        } finally {
            this.isLoading = false;
        }
    }
}
