import { LightningElement, api } from 'lwc';

let idCounter = 0;

export default class StatusListbox extends LightningElement {
    @api label;

    _options = [];
    _apiValue = '';
    _activeIndex = 0;
    _idPrefix = `statusListbox-${++idCounter}`;

    @api
    get options() {
        return this._options;
    }

    set options(newOptions) {
        this._options = newOptions || [];
        this._updateActiveIndex();
    }

    @api
    get value() {
        return this._apiValue;
    }

    set value(newValue) {
        this._apiValue = newValue;
        this._updateActiveIndex();
    }

    get displayOptions() {
        return this._options.map((opt, index) => ({
            value: opt.value,
            label: opt.label,
            id: `${this._idPrefix}-option-${index}`,
            selected: opt.value === this._apiValue
        }));
    }

    get activeOptionId() {
        if (this._options.length === 0) {
            return null;
        }
        return `${this._idPrefix}-option-${this._activeIndex}`;
    }

    _updateActiveIndex() {
        if (this._options.length === 0) {
            this._activeIndex = 0;
            return;
        }
        const idx = this._options.findIndex(
            (opt) => opt.value === this._apiValue
        );
        this._activeIndex = idx >= 0 ? idx : 0;
    }

    handleKeydown(event) {
        const { key } = event;
        const handledKeys = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];

        if (!handledKeys.includes(key)) {
            return;
        }

        event.preventDefault();

        if (this._options.length === 0) {
            return;
        }

        switch (key) {
            case 'ArrowDown':
                if (this._activeIndex < this._options.length - 1) {
                    this._activeIndex++;
                }
                break;
            case 'ArrowUp':
                if (this._activeIndex > 0) {
                    this._activeIndex--;
                }
                break;
            case 'Home':
                this._activeIndex = 0;
                break;
            case 'End':
                this._activeIndex = this._options.length - 1;
                break;
            case 'Enter':
            case ' ':
                this._selectActive();
                break;
        }
    }

    handleClick(event) {
        const target = event.target;
        if (target.tagName === 'LI' && target.getAttribute('role') === 'option') {
            const value = target.dataset.value;
            const index = this._options.findIndex((opt) => opt.value === value);
            if (index >= 0) {
                this._activeIndex = index;
                this._select(value);
            }
        }
    }

    _selectActive() {
        if (this._activeIndex >= 0 && this._activeIndex < this._options.length) {
            this._select(this._options[this._activeIndex].value);
        }
    }

    _select(value) {
        if (value === this._apiValue) {
            return;
        }
        this._apiValue = value;
        this.dispatchEvent(
            new CustomEvent('change', { detail: { value } })
        );
    }
}
