public class FamilyService {

    /**
     * Links parents to their children using NPSP Relationships.
     * 
     * For each entry in the map (child Contact Id -> parent Contact Id), creates an
     * NPSP Relationship record indicating the parent is the child's "Parent" (status Current).
     * NPSP's List Setting reciprocal method automatically creates the reverse record
     * showing the child as Son, Daughter, or Child (per the Relationship Lookup setting).
     *
     * Pairs that already have a relationship in either direction are skipped, making
     * the import idempotent and safe to re-run.
     *
     * Governor limits: uses at most 1 SOQL query and 1 DML statement regardless of
     * the number of pairs (tested up to 200 pairs per call).
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Filter to only valid pairs (non-null, non-self)
        Map<Id, Id> validPairs = new Map<Id, Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId != null && parentId != null && childId != parentId) {
                validPairs.put(childId, parentId);
            }
        }

        if (validPairs.isEmpty()) {
            return;
        }

        Set<Id> childIds = new Set<Id>(validPairs.keySet());

        // 1 SOQL query: retrieve all existing relationships involving any child contact
        // (in either direction), so we can detect duplicates for safe re-runs.
        List<npe4__Relationship__c> existingRels = [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :childIds
               OR npe4__RelatedContact__c IN :childIds
        ];

        // Build a set of contact-pair keys covering both directions for O(1) lookup
        Set<String> existingPairs = new Set<String>();
        for (npe4__Relationship__c rel : existingRels) {
            existingPairs.add(rel.npe4__Contact__c + '|' + rel.npe4__RelatedContact__c);
            existingPairs.add(rel.npe4__RelatedContact__c + '|' + rel.npe4__Contact__c);
        }

        // Build relationship records for pairs that don't already exist
        List<npe4__Relationship__c> newRels = new List<npe4__Relationship__c>();
        for (Id childId : validPairs.keySet()) {
            Id parentId = validPairs.get(childId);
            if (!existingPairs.contains(childId + '|' + parentId)) {
                newRels.add(new npe4__Relationship__c(
                    npe4__Contact__c = childId,
                    npe4__RelatedContact__c = parentId,
                    npe4__Type__c = 'Parent',
                    npe4__Status__c = 'Current'
                ));
            }
        }

        // 1 DML statement: insert all new relationship records.
        // NPSP's reciprocal trigger creates the matching reverse record automatically,
        // resolving the type to Son / Daughter / Child based on the child's gender
        // per the "Parent" Relationship Lookup setting.
        if (!newRels.isEmpty()) {
            insert newRels;
        }
    }
}
```

