```apex
public class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    public OPP_MajorGiftFollowUp_TDTM() {
        // No-arg constructor required for TDTM reflection-based instantiation
    }

    public override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        List<Task> tasks = new List<Task>();

        if (triggerAction == npsp.TDTM_Runnable.Action.AFTER_INSERT) {
            for (SObject sobj : newlist) {
                Opportunity opp = (Opportunity) sobj;
                if (isQualifying(opp)) {
                    tasks.add(buildTask(opp));
                }
            }
        } else if (triggerAction == npsp.TDTM_Runnable.Action.AFTER_UPDATE) {
            for (Integer i = 0; i < newlist.size(); i++) {
                Opportunity newOpp = (Opportunity) newlist[i];
                Opportunity oldOpp = (Opportunity) oldlist[i];
                if (isQualifying(newOpp) && !isQualifying(oldOpp)) {
                    tasks.add(buildTask(newOpp));
                }
            }
        }

        if (!tasks.isEmpty()) {
            insert tasks;
        }

        return null;
    }

    private Boolean isQualifying(Opportunity opp) {
        return opp.StageName == 'Closed Won'
            && opp.Amount != null
            && opp.Amount >= 5000;
    }

    private Task buildTask(Opportunity opp) {
        return new Task(
            Subject = 'Major gift thank-you call',
            Priority = 'High',
            Status = 'Not Started',
            WhatId = opp.Id,
            WhoId = opp.npsp__Primary_Contact__c,
            OwnerId = opp.OwnerId,
            ActivityDate = opp.CloseDate != null ? opp.CloseDate.addDays(3) : null
        );
    }
}
```

**Key design decisions:**

| Concern | How it's handled |
|---------|-----------------|
| TDTM dispatch | Class extends `npsp.TDTM_Runnable`, overrides `run()`, has no-arg constructor for `Type.newInstance()` |
| Deactivation | TDTM dispatcher only invokes active Trigger Handler records — no trigger file needed |
| Idempotency | On `AFTER_UPDATE`, the condition `isQualifying(new) && !isQualifying(old)` ensures edits to already-qualifying gifts produce no task |
| Bulk safety | Single loop builds a `List<Task>`; one `insert` statement; zero SOQL queries — safe for 200 records |
| Null safety | `Amount != null` guard (null comparisons in Apex yield false, but explicit guard is clearer); `CloseDate` null check before `.addDays()` |
| `DmlWrapper` return | Returns `null` since DML is performed directly, not through the TDTM DML batching mechanism |

