        }

        List<String> fields = new List<String>{'Id', 'Name'};

        if (Schema.sField.FB_Employee__c.Department__c.getDescribe().isReadable()) {
            fields.add('Department__c');
        }
        if (Schema.sField.FB_Employee__c.Salary__c.getDescribe().isReadable()) {
            fields.add('Salary__c');
        }
        if (Schema.sField.FB_Employee__c.Personal_Email__c.getDescribe().isReadable()) {
            fields.add('Personal_Email__c');
        }

        String query = 'SELECT ' + String.join(fields, ', ')
            + ' FROM FB_Employee__c ORDER BY Name ASC';

        List<SObject> results = Database.query(query);
        List<FB_Employee__c> employees = new List<FB_Employee__c>();
        for (SObject sobj : results) {
            employees.add((FB_Employee__c) sobj);
        }
        return employees;
    }
}
