public class ContactImportService {
    /**
     * Inserts the given contacts in a single DML statement.
     * The TAF action TA_Contact_CreateWelcomeTask is bypassed for this insert only,
     * so legacy imports do not create welcome tasks. All other Contact automation
     * (e.g. TA_Contact_FormatPhone) still runs.
     * The bypass is cleared after the insert, so any subsequent inserts in the
     * same transaction will behave normally.
     */
    public static void importContacts(List<Contact> contacts) {
        if (contacts == null || contacts.isEmpty()) {
            return;
        }

        MetadataTriggerHandler.bypass('TA_Contact_CreateWelcomeTask');
        try {
            insert contacts;
        } finally {
            MetadataTriggerHandler.clearBypass('TA_Contact_CreateWelcomeTask');
        }
    }
}
