public class TA_Contact_PreventDuplicateEmail implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String ERROR_MESSAGE = 'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        List<Contact> contacts = (List<Contact>) triggerNew;
        List<Contact> eligible = new List<Contact>();
        for (Contact c : contacts) {
            if (c.AccountId != null && c.Email != null) {
                eligible.add(c);
            }
        }
        if (eligible.isEmpty()) return;

        Map<String, Boolean> dbKeys = queryExistingKeys(getPairs(eligible), null);
        Map<String, Boolean> claimedKeys = new Map<String, Boolean>();

        for (Contact c : eligible) {
            String key = buildKey(c.AccountId, c.Email);
            if (dbKeys.containsKey(key) || claimedKeys.containsKey(key)) {
                c.addError(ERROR_MESSAGE);
            } else {
                claimedKeys.put(key, true);
            }
        }
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Contact> newContacts = (List<Contact>) triggerNew;
        List<Contact> oldContacts = (List<Contact>) triggerOld;

        List<Contact> eligible = new List<Contact>();
        Set<Id> eligibleIds = new Set<Id>();

        for (Integer i = 0; i < newContacts.size(); i++) {
            Contact c = newContacts[i];
            Contact o = oldContacts[i];
            Boolean emailChanged = (c.Email != o.Email);
            Boolean accountIdChanged = (c.AccountId != o.AccountId);
            if ((emailChanged || accountIdChanged) && c.AccountId != null && c.Email != null) {
                eligible.add(c);
                eligibleIds.add(c.Id);
            }
        }
        if (eligible.isEmpty()) return;

        Map<String, Boolean> dbKeys = queryExistingKeys(getPairs(eligible), eligibleIds);
        Map<String, Boolean> claimedKeys = new Map<String, Boolean>();

        for (Contact c : eligible) {
            String key = buildKey(c.AccountId, c.Email);
            if (dbKeys.containsKey(key) || claimedKeys.containsKey(key)) {
                c.addError(ERROR_MESSAGE);
            } else {
                claimedKeys.put(key, true);
            }
        }
    }

    private static List<List<String>> getPairs(List<Contact> contacts) {
        List<List<String>> pairs = new List<List<String>>();
        for (Contact c : contacts) {
            pairs.add(new List<String>{c.AccountId, c.Email});
        }
        return pairs;
    }

    private static String buildKey(Id accountId, String email) {
        return accountId + '|' + email.toLowerCase();
    }

    private static Map<String, Boolean> queryExistingKeys(List<List<String>> pairs, Set<Id> excludedIds) {
        Map<String, Boolean> result = new Map<String, Boolean>();
        if (pairs.isEmpty()) return result;

        List<Contact> existing;
        if (excludedIds != null && !excludedIds.isEmpty()) {
            existing = [SELECT Id, AccountId, Email FROM Contact WHERE (AccountId, Email) IN :pairs AND Id NOT IN :excludedIds];
        } else {
            existing = [SELECT Id, AccountId, Email FROM Contact WHERE (AccountId, Email) IN :pairs];
        }

        for (Contact c : existing) {
            result.put(buildKey(c.AccountId, c.Email), true);
        }
        return result;
    }
}
